import base64, fcntl, hashlib, json, os, pathlib, pwd, runpy, shutil, subprocess, sys, tempfile, time, urllib.request
EXPECTED = {'/opt/cliproxyapi/cpa-admission.py': 'f048dfde531b767f2cab9758b0056e7f7184e342d411876a0b4dca72cd30d39e', '/opt/cliproxyapi/cpa-admission.json': 'f8a9950354c26580e9470577ebed03ecf907e9fb50bf6e4b4c262120cb02f1ac', '/etc/systemd/system/cpa-admission.service': '886f82046b135dc0cad752424602ac99e9c808f93936d0f747762c43f46577e1', '/etc/vps-ssh-launcher/cpa-admission.sha256': '6846ddd9610483a58a18b3cfb654d90fed053dd9b241cdaf11ccfdd632d44271'}
PAYLOADS = {'/opt/cliproxyapi/cpa-admission.py': '', '/opt/cliproxyapi/cpa-admission.json': '', '/etc/systemd/system/cpa-admission.service': '', '/etc/vps-ssh-launcher/cpa-admission.sha256': 'MTMyNTU0NjUzNmM2ZWM1M2NlNmMzMTg0NDUzZDRiMjhkMzZkMjBjZTE4MmU4YWRmMDRiNDY2ZTc0ZjViMDlhOAo='}

def run(*args):
    return subprocess.run(args, check=True, capture_output=True, text=True, timeout=30).stdout.strip()
def health():
    with urllib.request.urlopen('http://127.0.0.1:8318/healthz', timeout=5) as r:
        h = json.load(r)
    assert h['status'] == 'ok'
    return h
def idle():
    h = health()
    for name, lane in h['lanes'].items():
        state = lane['state']
        if any(state.get(k) for k in ('inflight','pending','half_open_probe','hold_reason','cooldown_remaining')):
            raise RuntimeError('LANE_BUSY_OR_PROTECTED:'+name)
    if run('ss','-Htn','state','established','( dport = :8318 or sport = :8318 or dport = :8317 or sport = :8317 )'):
        raise RuntimeError('DATA_SOCKETS_BUSY')
    return h
if '--execute' in sys.argv:
    lock = open('/run/vps-ssh-launcher-maintenance.lock','a')
    fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
for name, digest in EXPECTED.items():
    p=pathlib.Path(name)
    assert not p.is_symlink() and hashlib.sha256(p.read_bytes()).hexdigest() == digest, 'BASELINE_DRIFT:'+p.name
assert run('systemctl','is-active','cpa-admission.service') == 'active'
print('BASELINE_MATCH=true',flush=True)
if '--execute' not in sys.argv:
    h=health()
    for name,lane in h['lanes'].items():
        print('PREFLIGHT',name,json.dumps(lane['state'],sort_keys=True))
    print('DEPLOY_RESULT=PREVIEW_ONLY',flush=True)
    raise SystemExit(0)
quiet = 0
for _ in range(25):
    try:
        idle()
        quiet += 1
    except RuntimeError as exc:
        if not str(exc).startswith(('LANE_BUSY_OR_PROTECTED:', 'DATA_SOCKETS_BUSY')):
            raise
        quiet = 0
    if quiet == 3:
        break
    time.sleep(2)
else:
    raise RuntimeError('DEPLOY_RESULT=NO_IDLE_WINDOW_NO_CHANGES')
backup=pathlib.Path('/root/cpa-admission-oauth-risk-backup-'+time.strftime('%Y%m%dT%H%M%SZ',time.gmtime()))
backup.mkdir(mode=0o700)
for name in EXPECTED:
    target=backup/pathlib.Path(name).name
    shutil.copy2(name,target)
    assert hashlib.sha256(target.read_bytes()).hexdigest()==EXPECTED[name]
for name in ('antigravity-risk.json','claude-risk.json'):
    p=pathlib.Path('/var/lib/cpa-admission')/name
    if p.exists():
        assert not p.is_symlink()
        shutil.copy2(p,backup/name)
# Never restore risk snapshots during rollback: that could discard a newer hold.
print('BACKUP_DIR='+str(backup),flush=True)
with tempfile.TemporaryDirectory(prefix='cpa-risk-candidate-',dir='/root') as tmp:
    stage=pathlib.Path(tmp)
    for name,payload in PAYLOADS.items():
        data=base64.b64decode(payload)
        (stage/pathlib.Path(name).name).write_bytes(data)
    ns=runpy.run_path(str(stage/'cpa-admission.py'))
    cfg=ns['load_config'](stage/'cpa-admission.json')
    for lane in cfg['lanes']:
        if lane['name'] in ('antigravity-oauth','claude-oauth'):
            state=pathlib.Path('/var/lib/cpa-admission')/lane['name'].replace('-oauth','-risk.json')
            if state.exists():
                ns['LaneState'](lane,state)
    # Match the proven maintenance fence used by cpa_recovery_workflow.ps1.
    workers=run('ps','-C','nginx','-o','euid=,args=')
    uids={line.split()[0] for line in workers.splitlines() if 'nginx: worker process' in line}
    assert len(uids)==1 and next(iter(uids)).isdigit(), 'NGINX_IDENTITY_UNVERIFIED'
    tag='cpa-oauth-risk-'+str(os.getpid())
    rule=['OUTPUT','-p','tcp','-d','127.0.0.1','--dport','8318','-m','owner','--uid-owner',next(iter(uids)),'-m','conntrack','--ctstate','NEW','-m','comment','--comment',tag,'-j','REJECT']
    fenced=False
    stopped=False
    replaced=False
    try:
        run('iptables','-w','5','-I',rule[0],'1',*rule[1:])
        fenced=True
        for _ in range(3):
            idle()
            time.sleep(1)
        stopped=True
        run('systemctl','stop','cpa-admission.service')
        state=pathlib.Path('/var/lib/cpa-admission/claude-risk.json')
        if not state.exists():
            fd=os.open(state,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
            with os.fdopen(fd,'w') as f:
                json.dump({'version':1,'not_before':0,'hold_reason':None},f)
                f.flush();os.fsync(f.fileno())
            user=pwd.getpwnam('nobody')
            os.chown(state,user.pw_uid,user.pw_gid)
        for lane in cfg['lanes']:
            if lane['name'] in ('antigravity-oauth','claude-oauth'):
                ns['LaneState'](lane,pathlib.Path('/var/lib/cpa-admission')/lane['name'].replace('-oauth','-risk.json'))
        replaced=True
        for name in EXPECTED:
            target=pathlib.Path(name)
            candidate=target.with_name(target.name+'.oauth-risk-new')
            assert not candidate.exists()
            shutil.copy2(stage/target.name,candidate)
            os.chmod(candidate,target.stat().st_mode & 0o777)
            os.chown(candidate,target.stat().st_uid,target.stat().st_gid)
            os.replace(candidate,target)
        run('systemctl','daemon-reload')
        run('/usr/local/libexec/cpa-admission-integrity-check')
        run('systemctl','start','cpa-admission.service')
        stopped=False
        for _ in range(20):
            try:
                h=health()
                break
            except (OSError,AssertionError):
                time.sleep(0.5)
        else:
            raise RuntimeError('READINESS_TIMEOUT')
        for name in ('antigravity-oauth','claude-oauth'):
            s=h['lanes'][name]['state']
            assert s['strict_backoff'] and s['state_persisted'] and not s['state_write_failed']
        for name,payload in PAYLOADS.items():
            assert pathlib.Path(name).read_bytes()==base64.b64decode(payload)
        print('DEPLOY_RESULT=HOST_LOADED_NO_GENERATION',flush=True)
    except BaseException:
        if stopped or replaced:
            run('systemctl','stop','cpa-admission.service')
            if replaced:
                for name in EXPECTED:
                    shutil.copy2(backup/pathlib.Path(name).name,name)
            run('systemctl','daemon-reload')
            run('systemctl','start','cpa-admission.service')
            print('ROLLBACK=FILES_RESTORED_RISK_STATE_PRESERVED',flush=True)
        raise
    finally:
        if fenced:
            run('iptables','-w','5','-D',*rule)
            print('FENCE_REMOVED=true',flush=True)
